import { useEffect, useRef } from 'react';
import { useStore } from '~/app/store/store';
import { TrnscTypeCd } from '~/shared/api/dtos/enums';

/**
 * 컴포넌트 라이프사이클 동안 초기값을 보존하는 훅
 * @param value 현재 값
 * @returns 저장된 초기값 또는 현재 값
 */
export function usePreserveInitialValue<T>(value: T | undefined): T | undefined {
  const initialValueRef = useRef<T | null>(null);

  useEffect(() => {
    if (initialValueRef.current === null && value !== undefined) {
      initialValueRef.current = value;
    }
  }, [value]);

  return initialValueRef.current || value;
}

/**
 * 거래 유형 코드를 전역 스토어에 저장하고 불러오는 훅
 * 앱 다시 시작 후에도 값 유지
 *
 * @param trnscTypeCd 현재 거래 유형 코드
 * @returns 저장된 거래 유형 코드 또는 현재 값
 */
export function usePreserveTrnscTypeCd(trnscTypeCd: TrnscTypeCd | undefined): TrnscTypeCd | undefined {
  // 전역 Zustand 스토어의 exchangeSlice에서 상태와 액션 가져오기
  const lastTrnscTypeCd = useStore((state) => state.exchangeSlice.lastTrnscTypeCd);
  const setLastTrnscTypeCd = useStore((state) => state.exchangeSlice.setLastTrnscTypeCd);

  // 전달된 trnscTypeCd가 있으면 스토어에 저장
  useEffect(() => {
    if (trnscTypeCd) {
      setLastTrnscTypeCd(trnscTypeCd);
    }
  }, [trnscTypeCd, setLastTrnscTypeCd]);

  // 스토어의 값 또는 현재 전달된 값 반환 (스토어 값 우선)
  const valueTouse = lastTrnscTypeCd || trnscTypeCd;

  if (!valueTouse) {
    console.warn('No preserved trnscTypeCd available', {
      current: trnscTypeCd,
      stored: lastTrnscTypeCd,
    });
  }

  return valueTouse;
}

/**
 * 토큰 ID를 전역 스토어에 저장하고 불러오는 훅
 * 앱 다시 시작 후에도 값 유지
 *
 * @param tokenId 현재 토큰 ID
 * @returns 저장된 토큰 ID 또는 현재 값
 */
export function usePreserveTokenId(tokenId: string | undefined): string | undefined {
  // 전역 Zustand 스토어의 exchangeSlice에서 상태와 액션 가져오기
  const storedTokenId = useStore((state) => state.exchangeSlice.tokenId);
  const setTokenId = useStore((state) => state.exchangeSlice.setTokenId);

  // 전달된 tokenId가 있으면 스토어에 저장
  useEffect(() => {
    if (tokenId) {
      setTokenId(tokenId);
    }
  }, [tokenId, setTokenId]);

  // 스토어의 값 또는 현재 전달된 값 반환 (스토어 값 우선)
  const valueToUse = storedTokenId || tokenId;

  if (!valueToUse) {
    console.warn('No preserved tokenId available', {
      current: tokenId,
      stored: storedTokenId,
    });
  }

  return valueToUse;
}
