import { ErrorBoundary, ErrorBoundaryFallbackProps } from '@suspensive/react';
import { useEffect, useRef } from 'react';
import {
  usePreserveTrnscTypeCd,
  usePreserveTokenId,
} from '~/widgets/exchange-funnel-router/lib/use-preserve-initial-value';
import { ExchangeFunnelRouter } from '~/widgets/exchange-funnel-router/ui/exchange-funnel-router';
import { ExchangeErrorFallback } from '~/widgets/fallbacks/exchange-error-fallback';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { BaseExchangeContext } from '~/entities/exchange/model/schemas';
import { TrnscTypeCd } from '~/shared/api/dtos/enums';
import { closeWebview } from '~/shared/api/web-view';

type RouterState = Record<string, any>;

// 거래 유형 코드 추출 및 검증 유틸리티
const extractTrnscTypeCd = (data: any): TrnscTypeCd | undefined => {
  if (!data) return undefined;
  const typeCd = data.trnscTypeCd;

  // 유효한 거래 유형 코드인지 확인
  const validCodes = Object.values(TrnscTypeCd);
  if (typeCd && validCodes.includes(typeCd as TrnscTypeCd)) {
    return typeCd as TrnscTypeCd;
  }
  return undefined;
};

// 토큰 ID 추출 유틸리티
const extractTokenId = (data: any): string | undefined => {
  if (!data) return undefined;
  const { tokenId } = data;

  // 유효한 토큰 ID 확인 (문자열이어야 함)
  if (tokenId && typeof tokenId === 'string' && tokenId.trim() !== '') {
    return tokenId;
  }
  return undefined;
};

export const Exchange = () => {
  const { routerState } = useGetRouterState<RouterState>();

  // 마지막으로 확인된 유효한 거래 유형 코드 추적
  const lastValidTrnscTypeRef = useRef<TrnscTypeCd | undefined>(undefined);
  // 마지막으로 확인된 유효한 토큰 ID 추적
  const lastValidTokenIdRef = useRef<string | undefined>(undefined);

  // context 찾기 - context가 없으면 routerState 자체를 사용
  const contextEntry = Object.entries(routerState ?? {}).find(([key]) => key.endsWith('.context'));
  const contextData = contextEntry?.[1] as BaseExchangeContext | undefined;
  const baseData = contextData || routerState;

  // 거래 유형 코드 추출 및 fallback
  const currentTrnscTypeCd = extractTrnscTypeCd(baseData);
  // 토큰 ID 추출
  const currentTokenId = extractTokenId(baseData);

  // 유효한 거래 유형 코드가 발견되면 참조 업데이트
  useEffect(() => {
    if (currentTrnscTypeCd) {
      lastValidTrnscTypeRef.current = currentTrnscTypeCd;
    }
  }, [currentTrnscTypeCd]);

  // 유효한 토큰 ID가 발견되면 참조 업데이트
  useEffect(() => {
    if (currentTokenId) {
      lastValidTokenIdRef.current = currentTokenId;
    }
  }, [currentTokenId]);

  // 커스텀 훅을 사용하여 trnscTypeCd의 초기값 보존
  // 현재 값이 없으면 마지막 유효한 값 사용
  const trnscTypeCdToUse = currentTrnscTypeCd || lastValidTrnscTypeRef.current;
  const preservedTrnscTypeCd = usePreserveTrnscTypeCd(trnscTypeCdToUse);

  // 커스텀 훅을 사용하여 tokenId의 초기값 보존
  // 현재 값이 없으면 마지막 유효한 값 사용
  const tokenIdToUse = currentTokenId || lastValidTokenIdRef.current;
  const preservedTokenId = usePreserveTokenId(tokenIdToUse);

  // 실제 사용할 config 객체
  const config = {
    ...baseData,
    // 보존된 값을 사용 - 절대 undefined가 되지 않도록 보장
    trnscTypeCd: preservedTrnscTypeCd,
    tokenId: preservedTokenId,
  };

  // console.log({ routerState });
  // console.log('trnscTypeCd data flow:', {
  //   fromBaseData: baseData?.trnscTypeCd,
  //   current: trnscTypeCdToUse,
  //   preserved: preservedTrnscTypeCd,
  //   lastValid: lastValidTrnscTypeRef.current,
  // });
  // console.log('tokenId data flow:', {
  //   fromBaseData: baseData?.tokenId,
  //   current: tokenIdToUse,
  //   preserved: preservedTokenId,
  //   lastValid: lastValidTokenIdRef.current,
  // });

  return (
    <ErrorBoundary
      fallback={(props: ErrorBoundaryFallbackProps) => (
        <ExchangeErrorFallback
          error={props.error}
          reset={props.reset}
          onConfirmClick={() => {
            closeWebview();
          }}
        />
      )}
    >
      <ExchangeFunnelRouter
        config={config}
        onProcessingError={(error) => {
          //console.log('onProcessingError', error);
          throw error;
        }}
        onProcessingSuccess={(result) => {
          //console.log('onProcessingSuccess', result);
        }}
        onComplete={(redirectPath) => {
          closeWebview({ redirectPath: redirectPath ?? undefined });
        }}
      />
    </ErrorBoundary>
  );
};
