import { Suspense } from '@suspensive/react';
import { SwitchCase } from '@toss/react';
import { lazy } from 'react';
import { FullScreenLoading } from '~/widgets/loading/full-screen-loading';
import { BaseExchangeContext } from '~/entities/exchange/model/schemas';
import { TrnscTypeCd } from '~/shared/api/dtos/enums';

const ConvertToTokenFunnel = lazy(() =>
  import('~/widgets/exchange-convert-to-token-funnel/ui/convert-to-token-funnel').then((module) => ({
    default: module.ConvertToTokenFunnel,
  })),
);

const ConvertToDepositFunnel = lazy(() =>
  import('~/widgets/exchange-convert-to-deposit-funnel/ui/convert-to-deposit-to-funnel').then((module) => ({
    default: module.ConvertToDepositFunnel,
  })),
);

const PaymentFunnel = lazy(() =>
  import('~/widgets/exchange-payment-funnel/ui/payment-funnel').then((module) => ({
    default: module.PaymentFunnel,
  })),
);

const RemittanceFunnel = lazy(() =>
  import('~/widgets/exchange-remittance-funnel/ui/remittance-funnel').then((module) => ({
    default: module.RemittanceFunnel,
  })),
);

export type ExchangeFunnelProps = {
  config: BaseExchangeContext;
  onProcessingStart?: () => void;
  onProcessingSuccess?: (result: any) => void;
  onProcessingError?: (error: Error) => void;
  onComplete?: (redirectPath: string | undefined | null) => void;
};

export const ExchangeFunnelRouter = ({
  config,
  onProcessingStart,
  onProcessingSuccess,
  onProcessingError,
  onComplete,
}: ExchangeFunnelProps) => {
  return (
    <Suspense fallback={<FullScreenLoading />}>
      {!config.trnscTypeCd ? (
        <div className="flex h-screen w-full items-center justify-center p-4 text-center">
          <div className="rounded-lg bg-red-50 p-4 text-red-800">
            <h3 className="mb-2 text-lg font-medium">거래 유형 코드 누락</h3>
            <p>거래 유형 코드가 없습니다. 올바른 경로로 접근해주세요.</p>
          </div>
        </div>
      ) : (
        <SwitchCase
          value={config.trnscTypeCd as TrnscTypeCd}
          caseBy={{
            [TrnscTypeCd.전환입금]: (
              <ConvertToTokenFunnel
                config={config}
                onProcessingStart={onProcessingStart}
                onProcessingSuccess={onProcessingSuccess}
                onProcessingError={onProcessingError}
                onComplete={onComplete}
              />
            ),
            [TrnscTypeCd.예금전환]: (
              <ConvertToDepositFunnel
                config={config}
                onProcessingStart={onProcessingStart}
                onProcessingSuccess={onProcessingSuccess}
                onProcessingError={onProcessingError}
                onComplete={onComplete}
              />
            ),
            [TrnscTypeCd.결제]: (
              <PaymentFunnel
                config={config}
                onProcessingStart={onProcessingStart}
                onProcessingSuccess={onProcessingSuccess}
                onProcessingError={onProcessingError}
                onComplete={onComplete}
              />
            ),
            [TrnscTypeCd.송금]: (
              <RemittanceFunnel
                config={config}
                onProcessingStart={onProcessingStart}
                onProcessingSuccess={onProcessingSuccess}
                onProcessingError={onProcessingError}
                onComplete={onComplete}
              />
            ),
          }}
        />
      )}
    </Suspense>
  );
};
